-- Persistent notifications are generated by database triggers so they are not dependent on a browser session.
create schema if not exists app_private;
revoke all on schema app_private from public, anon, authenticated;

create or replace function app_private.create_user_notification(p_user_id uuid,p_title text,p_body text,p_type text,p_action_url text default null)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if p_user_id is null then return; end if;
  if exists(select 1 from public.platform_notifications n where n.user_id=p_user_id and n.title=p_title and n.notification_type=p_type and coalesce(n.action_url,'')=coalesce(p_action_url,'') and n.created_at>now()-interval '23 hours') then return; end if;
  insert into public.platform_notifications(user_id,title,body,notification_type,action_url,created_by)
  values(p_user_id,p_title,p_body,p_type,p_action_url,null);
end $$;

create or replace function app_private.notify_organization_members(p_organization_id uuid,p_title text,p_body text,p_type text,p_action_url text default null,p_extra_user_id uuid default null)
returns void language plpgsql security definer set search_path = '' as $$
declare recipient record;
begin
  for recipient in select distinct ids.user_id from (
    select om.user_id from public.organization_memberships om where om.organization_id=p_organization_id
    union select p_extra_user_id where p_extra_user_id is not null
  ) ids loop
    perform app_private.create_user_notification(recipient.user_id,p_title,p_body,p_type,p_action_url);
  end loop;
end $$;

create or replace function app_private.notify_rental_request_changes()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.status is distinct from old.status then
    perform app_private.notify_organization_members(new.organization_id,'تحديث حالة طلب التأجير','تم تحديث حالة طلب '||coalesce(new.title,'التأجير')||' إلى: '||new.status||'.','rental_request_update','/workspace/company/requests',new.created_by);
  end if;
  return new;
end $$;

create or replace function app_private.notify_rental_offer_changes()
returns trigger language plpgsql security definer set search_path = '' as $$
declare request_row record;
begin
  if tg_op='INSERT' then
    select rr.organization_id,rr.created_by,rr.title into request_row from public.rental_requests rr where rr.id=new.request_id;
    if request_row.organization_id is not null then
      perform app_private.notify_organization_members(request_row.organization_id,'وصل عرض جديد لطلب شركتك','وصل عرض جديد على طلب '||coalesce(request_row.title,'التأجير')||'. افتح الطلب لمراجعة التفاصيل.','rental_offer_received','/workspace/company/requests',request_row.created_by);
    end if;
    return new;
  end if;
  if new.status is distinct from old.status then
    perform app_private.notify_organization_members(new.organization_id,'تم تحديث حالة عرضك','تم تحديث حالة عرضك المقدم على طلب التأجير. افتح حسابك لمتابعة التفاصيل.','rental_offer_update','/workspace/supplier/requests',new.created_by);
  end if;
  return new;
end $$;

drop trigger if exists rental_requests_notify_status on public.rental_requests;
create trigger rental_requests_notify_status after update of status on public.rental_requests for each row execute function app_private.notify_rental_request_changes();
drop trigger if exists rental_offers_notify_changes on public.rental_offers;
create trigger rental_offers_notify_changes after insert or update of status on public.rental_offers for each row execute function app_private.notify_rental_offer_changes();

create or replace function app_private.send_expiry_notifications()
returns integer language plpgsql security definer set search_path = '' as $$
declare sent_count integer:=0; item record; days_left integer; cairo_today date:=(now() at time zone 'Africa/Cairo')::date;
begin
  for item in select vp.id,vp.organization_id,vp.created_by,vp.ends_at,v.make,v.model
    from public.vehicle_promotions vp join public.vehicles v on v.id=vp.vehicle_id
    where vp.status in ('active','approved') and vp.ends_at is not null
      and (vp.ends_at at time zone 'Africa/Cairo')::date in (cairo_today+7,cairo_today+3,cairo_today+1)
  loop
    days_left:=(item.ends_at at time zone 'Africa/Cairo')::date-cairo_today;
    perform app_private.notify_organization_members(item.organization_id,case when days_left=1 then 'إعلان سيارتك ينتهي غدًا' else 'اقترب موعد انتهاء إعلان سيارتك' end,'يتبقى '||days_left||' أيام على انتهاء إعلان '||item.make||' '||item.model||'. يمكنك تجديد الباقة من حسابك.','advertisement_expiring_'||days_left,'/workspace/owner/vehicles',item.created_by);
    sent_count:=sent_count+1;
  end loop;
  for item in select cs.id,cs.organization_id,cs.created_by,cs.ends_at,cs.plan_name from public.company_subscriptions cs
    where cs.status='active' and cs.ends_at is not null and (cs.ends_at at time zone 'Africa/Cairo')::date in (cairo_today+7,cairo_today+3,cairo_today+1)
  loop
    days_left:=(item.ends_at at time zone 'Africa/Cairo')::date-cairo_today;
    perform app_private.notify_organization_members(item.organization_id,case when days_left=1 then 'اشتراك شركتك ينتهي غدًا' else 'اقترب موعد انتهاء اشتراك شركتك' end,'يتبقى '||days_left||' أيام على انتهاء اشتراك '||coalesce(item.plan_name,'الشركة')||'. جدد الاشتراك لتجنب انقطاع المزايا.','subscription_expiring_'||days_left,'/workspace/company',item.created_by);
    sent_count:=sent_count+1;
  end loop;
  for item in select v.id,v.organization_id,v.created_by,v.registration_expires_at,v.make,v.model from public.vehicles v
    where v.review_status='approved' and v.registration_expires_at is not null and (v.registration_expires_at at time zone 'Africa/Cairo')::date in (cairo_today+7,cairo_today+3,cairo_today+1)
  loop
    days_left:=(item.registration_expires_at at time zone 'Africa/Cairo')::date-cairo_today;
    perform app_private.notify_organization_members(item.organization_id,case when days_left=1 then 'رسوم تسجيل سيارتك تنتهي غدًا' else 'اقترب موعد تجديد تسجيل السيارة' end,'يتبقى '||days_left||' أيام على انتهاء تسجيل '||item.make||' '||item.model||'. استكمل التجديد من حسابك.','vehicle_registration_expiring_'||days_left,'/workspace/owner/vehicles',item.created_by);
    sent_count:=sent_count+1;
  end loop;
  return sent_count;
end $$;

create or replace function public.run_mycar_expiry_notifications()
returns integer language sql security definer set search_path = '' as $$ select app_private.send_expiry_notifications(); $$;
revoke all on function public.run_mycar_expiry_notifications() from public,anon,authenticated;
grant execute on function public.run_mycar_expiry_notifications() to postgres;

create extension if not exists pg_cron with schema pg_catalog;
do $$ begin
  if not exists(select 1 from cron.job where jobname='mycar-expiry-notifications-daily') then
    perform cron.schedule('mycar-expiry-notifications-daily','0 6 * * *','select public.run_mycar_expiry_notifications();');
  end if;
end $$;
